/**
 * Animal silhouettes for puzzle grids.
 *
 * Each silhouette is a professionally drawn profile taken from a source
 * that is explicitly public domain or CC0 (PhyloPic CC0 / Public Domain
 * Mark, or Openclipart CC0). Files were downloaded, normalized to filled
 * silhouettes, and simplified. See `src/lib/shapes/animals/SOURCES.md`
 * for the source URL, author, and license of every animal. Nothing here
 * is copied from Neoformix or from any other commercial puzzle book.
 */

export interface AnimalSource {
  provider: "phylopic" | "openclipart" | "commons";
  url: string;
  author: string;
  license: string;
  /** Taxon or original title. */
  credit?: string;
}

export interface AnimalDef {
  key: string;
  label: string;
  /** Smallest N×N canvas that keeps the silhouette recognisable. */
  minSize: number;
  /** Theme / search aliases (lowercase). The label and key are matched too. */
  aliases: string[];
  /** Closed SVG path in authoring coordinates (profile silhouette). */
  path: string;
  /** Optional torso box in the same coordinates, used to sit a sudoku inside the body. */
  focus?: [number, number, number, number];
  /** Override the natural bounding-box aspect (width / height). */
  aspect?: number;
  source: AnimalSource;
}

